window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["model-routing"]={"title":"模型路由与级联：把不同难度请求分给足够的能力","subtitle":"从直接路由、先小后大和质量差预测，到升级阈值、级联延迟、公平风险与在线再校准。","thesis":"模型路由在应用层为每个请求选择完整模型或服务，目标是在质量与风险门槛下减少期望成本。省钱的关键不是小模型占比，而是<b>正确识别哪些请求可以安全下放</b>；路由错误会集中伤害困难、长尾和高风险切片。","quality":{"contractVersion":2,"examples":[{"section":5,"evidence":{"setup":"1000 笔退款按“需要强模型概率”排序","rule":"若门槛是质量≥93%、错放≤15","steps":"τ=.5 是最低成本可行点","interpretation":"仍需对该切片强制升级"}}],"formulas":[{"id":"routing-constrained-objective","section":3,"formulaIndex":1,"symbols":[{"name":"m","meaning":"把请求映射到候选模型的路由策略","evidence":"所选模型 m(x)"},{"name":"x","meaning":"当前请求","evidence":"输入请求 x"},{"name":"Ecost","meaning":"路由策略的期望模型成本","evidence":"最低期望成本策略"},{"name":"c","meaning":"一次模型选择的成本","evidence":"成本 c"},{"name":"Equality","meaning":"路由后总体期望质量","evidence":"平均质量"},{"name":"q","meaning":"所选模型在请求上的质量结果","evidence":"质量 q"},{"name":"Q0","meaning":"总体质量下限","evidence":"质量下限 Q0"},{"name":"Risk","meaning":"关键切片的错误下放风险","evidence":"关键切片风险 Riskk"},{"name":"k","meaning":"关键切片编号","evidence":"逐切片硬约束"},{"name":"R","meaning":"关键切片允许的风险上限","evidence":"上限 Rk"}]},{"id":"routing-cascade-cost-time","section":4,"formulaIndex":1,"symbols":[{"name":"ECost","meaning":"级联平均调用成本","evidence":"输出期望成本 ECost"},{"name":"Cs","meaning":"小模型单次成本","evidence":"小模型成本 Cs"},{"name":"r","meaning":"请求升级到强模型的比例","evidence":"升级率 r"},{"name":"Cl","meaning":"强模型单次成本","evidence":"强模型成本 Cl"},{"name":"ETime","meaning":"级联平均延迟","evidence":"期望延迟 ETime"},{"name":"Ts","meaning":"小模型延迟","evidence":"小模型延迟 Ts"},{"name":"Tjudge","meaning":"升级判定延迟","evidence":"判定延迟 Tjudge"},{"name":"Tl","meaning":"强模型延迟","evidence":"强模型延迟 Tl"}]}],"termReviews":[{"term":"级联","section":2,"evidence":"输出规则路由、直接路由、级联或并行选择"},{"term":"反事实","section":3,"evidence":"补足下放样本的反事实"},{"term":"校准","section":6,"evidence":"输出经独立集校准的“升级可修复概率”"}],"sectionContracts":[{"section":1,"definition":{"answer":"模型路由按每个请求在已有候选模型或人工路径间选择。","evidence":"路由把一次选型变成逐请求决策"},"problem":{"answer":"它让简单请求少付计算成本并升级异常与高风险请求。","evidence":"为何不该付相同计算成本"},"inputOutput":{"answer":"输入请求风险和候选证据，输出模型、人工或拒绝路径。","evidence":"输出小模型、强模型、人工或拒绝路径"},"mechanism":{"answer":"逐请求判断已有候选谁足够，硬风险规则优先。","evidence":"高风险硬规则优先于概率分数"},"interpretation":{"answer":"下放表示现有证据支持小模型足够，不表示天然简单。","evidence":"不表示请求天然简单"},"boundary":{"answer":"路由不能创造所有候选都缺失的能力。","evidence":"不会创造候选都没有的能力"}},{"section":2,"definition":{"answer":"路由架构包括规则、直接路由、级联和并行选择。","evidence":"直接路由、级联和并行选择"},"problem":{"answer":"它决定是在调用前选择还是根据首答证据升级。","evidence":"还是先让小模型回答再决定升级"},"inputOutput":{"answer":"输入时点信号成本和 SLO，输出一种适合的路由形态。","evidence":"输出规则路由、直接路由、级联或并行选择"},"mechanism":{"answer":"调用前信号直接选，首答验证信号用于级联。","evidence":"首答和验证信号适合级联"},"interpretation":{"answer":"并行以更高成本换低墙钟时间，级联增加升级尾延迟。","evidence":"并行用成本换墙钟时间"},"boundary":{"answer":"首阶段有副作用时不得无审查地继续级联。","evidence":"不得无审查级联"}},{"section":3,"definition":{"answer":"路由目标是在切片风险硬约束下最小化期望成本。","evidence":"数学目标必须带切片硬约束"},"problem":{"answer":"它防止多数简单样本高分抵消少数困难请求错放。","evidence":"路由器会学到什么危险捷径"},"inputOutput":{"answer":"输入请求模型成本质量和门槛，输出最低成本策略。","evidence":"输出满足逐切片硬约束的最低期望成本策略"},"mechanism":{"answer":"预测强弱模型相对收益，并用双跑补反事实。","evidence":"用随机双跑补足下放样本的反事实"},"interpretation":{"answer":"平均质量合格不代表每个关键切片风险可接受。","evidence":"平均质量不能抵消少数切片错放"},"boundary":{"answer":"没有下放反事实时不能声称错放风险已被正确估计。","evidence":"下放样本的反事实"}},{"section":4,"definition":{"answer":"级联成本包含所有请求的小模型成本和升级请求的强模型成本。","evidence":"级联期望成本和延迟怎样计算"},"problem":{"answer":"它解释平均费用与升级请求串行尾延迟如何形成。","evidence":"平均成本真是 ¥0.045 吗"},"inputOutput":{"answer":"输入成本升级率和延迟，输出期望成本与期望延迟。","evidence":"输出期望成本 ECost 与期望延迟 ETime"},"mechanism":{"answer":"所有请求先跑小模型，升级者再串行判定和跑强模型。","evidence":"所有请求先付 Cs"},"interpretation":{"answer":"零点零四五只包含给定模型调用假设。","evidence":"0.045 元成立于给定调用假设"},"boundary":{"answer":"评分器、失败、人工和副作用必须另计。","evidence":"不含评分器、失败和人工"}},{"section":5,"definition":{"answer":"阈值案例把升级分数与阈值比较后选择大小模型。","evidence":"阈值怎样改变覆盖、错误与成本"},"problem":{"answer":"它展示更保守阈值如何交换升级成本与错放风险。","evidence":"τ=.5 与 τ=.3 如何取舍"},"inputOutput":{"answer":"输入请求分数阈值和结果，输出最低成本可行阈值。","evidence":"输出满足质量与错放门槛的最低成本阈值"},"mechanism":{"answer":"降低阈值会增加升级并减少困难请求错放。","evidence":"τ 降低会增加升级、成本并减少错放"},"interpretation":{"answer":"全局可行点只有在各关键切片也通过时才能采用。","evidence":"只在全局与所有关键切片同时通过时可选"},"boundary":{"answer":"高风险切片失败必须强制升级而非平均抵消。","evidence":"不能靠全局平均掩盖"}},{"section":6,"definition":{"answer":"路由信号是决策时可获得且经校准的升级收益证据。","evidence":"路由信号必须在决策时可得且可校准"},"problem":{"answer":"它避免用未来标签或模型自信冒充可部署特征。","evidence":"哪些特征真正能预测强模型比小模型更有价值"},"inputOutput":{"answer":"输入当时可得特征，输出校准后的升级可修复概率。","evidence":"输出经独立集校准的“升级可修复概率”"},"mechanism":{"answer":"在独立集校准分数，并按切片检查可靠性。","evidence":"分数可靠性必须按切片检查"},"interpretation":{"answer":"未校准自报置信度不等于真实升级收益概率。","evidence":"模型自报置信度不能未经校准"},"boundary":{"answer":"训练使用未来或强模型后验信息属于数据泄漏。","evidence":"训练时使用未来标签或强模型后验信息会数据泄漏"}},{"section":7,"definition":{"answer":"公平路由评测比较不同语言领域群体和风险切片的服务结果。","evidence":"错误下放会集中在谁身上"},"problem":{"answer":"它发现平均质量隐藏的长尾系统性弱模型服务。","evidence":"为什么长尾语言和专业用户仍可能系统性得到弱模型"},"inputOutput":{"answer":"输入切片，输出下放错放升级收益及置信区间。","evidence":"输出各切片下放率、强对小错率、错放率、升级收益与置信区间"},"mechanism":{"answer":"逐切片统计并比较路由前后的错误和服务质量。","evidence":"平均合格可能隐藏长尾用户持续收到弱模型"},"interpretation":{"answer":"公平限制不可接受差距，不要求升级比例完全相同。","evidence":"不是强求相同升级比例"},"boundary":{"answer":"高影响任务可用规则直接绕过学习路由。","evidence":"高影响任务可直接绕过学习路由"}},{"section":8,"definition":{"answer":"在线路由治理持续探索下放反事实并监控漂移。","evidence":"路由器上线也需要探索、监控与回退"},"problem":{"answer":"它处理模型价格流量变化导致旧阈值立刻失真的问题。","evidence":"旧阈值为什么会立即失真"},"inputOutput":{"answer":"输入版本分数原因和反馈，输出审计重校准或回退。","evidence":"输出探索审计、重校准、金丝雀或保守回退动作"},"mechanism":{"answer":"随机双跑估错放，漂移后重新收集数据并校准。","evidence":"随机双跑让系统看见下放反事实"},"interpretation":{"answer":"错放超预算说明应先收紧执行路径而非只改显示指标。","evidence":"错放超预算时先禁用危险动作或全量升级"},"boundary":{"answer":"不可逆工具只能由一个获批路径执行。","evidence":"不能只移动阈值掩盖根因"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>区分选型、路由与 MoE；推导级联成本和升级阈值；评测错误下放与级联延迟；设计校准、漂移与安全回退。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>路由把一次选型变成逐请求决策<span class=\"dd-badge intuition\">直觉</span></h2><p class=\"dd-lead\">同一退款系统里，FAQ 与跨政策异常为何不该付相同计算成本？</p><p>简单状态查询可由小模型完成，证据冲突、金额异常或高权限请求升级强模型或人工。静态选型为整个组件固定模型；动态路由根据当前输入与运行证据选择；MoE 则是一个模型内部为 token 选择专家，用户通常不直接控制完整模型切换。</p><p>路由不会创造底层模型没有的能力，只在已有候选之间分配。若所有模型在某切片都失败，路由器最多选出不同的失败；应先通过选型与评测建立逐样本基线。</p><div class=\"dd-note\"><b>真正目标：</b>最大化安全可下放覆盖率，而不是最大化“小模型调用率”。后者会诱导把困难请求错误地下放。</div><p>模型路由输入当前请求、风险规则、候选模型能力和运行证据，输出小模型、强模型、人工或拒绝路径。它逐请求选择已有能力，不会创造候选都没有的能力；下放表示证据显示小模型足够，不表示请求天然简单。高风险硬规则优先于概率分数。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>直接路由、级联和并行选择<span class=\"dd-badge eng\">架构</span></h2><p class=\"dd-lead\">是在调用前选模型，还是先让小模型回答再决定升级？</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>形态</th><th>过程</th><th>优势</th><th>代价</th></tr></thead><tbody><tr><td>规则路由</td><td>按领域/风险/长度选择</td><td>可解释、无额外模型</td><td>边界粗、维护规则</td></tr><tr><td>直接路由</td><td>轻量分类器先选 S/M/L</td><td>困难请求不先浪费小模型</td><td>仅凭输入可能判断不足</td></tr><tr><td>级联</td><td>先跑 S，低置信再跑 L</td><td>利用首答、验证与检索信号</td><td>升级请求更慢且首答可能污染</td></tr><tr><td>并行选择</td><td>多个模型同时跑再选择</td><td>低墙钟延迟、候选多</td><td>成本高、选择器也会错</td></tr></tbody></table></div><p>高风险请求可用确定规则强制 L/人工，不交给概率路由器；低风险长尾可级联。架构应按错误成本和延迟 SLO组合，而不是全站只用一个阈值。</p><p>架构选择输入决策时点、可用信号、错误成本和延迟 SLO，输出规则路由、直接路由、级联或并行选择。调用前信号适合直接选择，首答和验证信号适合级联，并行用成本换墙钟时间；没有一种形态适合所有请求。首阶段可能产生副作用时不得无审查级联。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>数学目标必须带切片硬约束<span class=\"dd-badge math\">机制</span></h2><p class=\"dd-lead\">只最小化平均费用，路由器会学到什么危险捷径？</p><div class=\"dd-formula\"><math display=\"block\" aria-label=\"带逐切片约束的模型路由目标\"><munder><mi>min</mi><mi>m</mi></munder><mi>Ecost</mi><mo>[</mo><mi>c</mi><mo>(</mo><mi>m</mi><mo>(</mo><mi>x</mi><mo>)</mo><mo>)</mo><mo>]</mo><mo>,</mo><mtext>subject to</mtext><mi>Equality</mi><mo>[</mo><mi>q</mi><mo>(</mo><mi>m</mi><mo>(</mo><mi>x</mi><mo>)</mo><mo>,</mo><mi>x</mi><mo>)</mo><mo>]</mo><mo>≥</mo><mi>Q0</mi><mo>,</mo><msub><mi>Risk</mi><mi>k</mi></msub><mo>≤</mo><msub><mi>R</mi><mi>k</mi></msub></math></div><p>平均约束允许多数简单请求的高分抵消少数越权错误。应为语言、领域、风险和用户群设置最低质量/最大错误下放率；样本少时报告区间并采用保守上界。</p><p>训练目标最好预测“强模型相对小模型的质量增益”而非绝对难度：若两者都对，升级浪费；若两者都错，升级也无收益；只有强对小错的样本最值得升级。质量标签来自独立评分器与人工，不能用强模型自评当无偏真值。</p><div class=\"dd-note warn\"><b>选择偏差：</b>线上只给被升级样本运行强模型，就看不到下放样本的反事实强模型表现；需随机探索或离线双跑建立无偏数据。</div><p>路由优化输入请求 x、所选模型 m(x)、成本 c、质量 q、质量下限 Q0、关键切片风险 Riskk 和上限 Rk，输出满足逐切片硬约束的最低期望成本策略。平均质量不能抵消少数切片错放；训练应预测强模型相对收益，并用随机双跑补足下放样本的反事实。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>级联期望成本和延迟怎样计算<span class=\"dd-badge math\">推导</span></h2><p class=\"dd-lead\">小模型 ¥0.02、强模型 ¥0.10，升级 25% 时平均成本真是 ¥0.045 吗？</p><p>若所有请求先跑小模型，升级后再跑强模型，忽略其他组件时：</p><div class=\"dd-formula\"><math display=\"block\" aria-label=\"级联期望成本与延迟\"><mi>ECost</mi><mo>=</mo><mi>Cs</mi><mo>+</mo><mi>r</mi><mo>×</mo><mi>Cl</mi><mo>;</mo><mi>ETime</mi><mo>≈</mo><mo>(</mo><mn>1</mn><mo>−</mo><mi>r</mi><mo>)</mo><mo>×</mo><mi>Ts</mi><mo>+</mo><mi>r</mi><mo>×</mo><mo>(</mo><mi>Ts</mi><mo>+</mo><mi>Tjudge</mi><mo>+</mo><mi>Tl</mi><mo>)</mo></math></div><p>代入 Cₛ=.02、Cₗ=.10、r=.25，平均调用成本=.045。若直接路由只在前置分类器后选一个模型，则是 <code>Crouter +(1−r)Cₛ+rCₗ</code>。两者费用接近时，级联仍让升级请求承受 S+L 的串行尾延迟。</p><p>真实成本还包括评分器、重试、检索、人工和失败。若小模型首答写入对话或触发工具，即使后来升级也可能留下污染或副作用，因此级联首阶段应默认无副作用、输出只作为候选证据。</p><p>级联核算输入小模型成本 Cs、强模型成本 Cl、升级率 r、小模型延迟 Ts、判定延迟 Tjudge 和强模型延迟 Tl，输出期望成本 ECost 与期望延迟 ETime。所有请求先付 Cs，升级请求再付 Cl 和串行延迟；0.045 元成立于给定调用假设，不含评分器、失败和人工。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>运行示例：阈值怎样改变覆盖、错误与成本<span class=\"dd-badge math\">逐步演算</span></h2><p class=\"dd-lead\">1000 笔退款按“需要强模型概率”排序，τ=.5 与 τ=.3 如何取舍？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 700 260\" role=\"img\" aria-label=\"退款请求按升级分数路由到小模型和强模型并由抽样审计回流\"><defs><marker id=\"mr1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#6b7484\"/></marker></defs><rect x=\"18\" y=\"88\" width=\"130\" height=\"68\" rx=\"9\" fill=\"#21252d\" stroke=\"#6b8cbe\"/><text x=\"83\" y=\"114\" text-anchor=\"middle\" class=\"svg-t\">1000 个请求</text><text x=\"83\" y=\"136\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">风险规则先拦截</text><path d=\"M148,122 L208,122\" stroke=\"#6b7484\" marker-end=\"url(#mr1)\"/><rect x=\"210\" y=\"88\" width=\"150\" height=\"68\" rx=\"9\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"285\" y=\"114\" text-anchor=\"middle\" class=\"svg-t\">路由分数 g(x)</text><text x=\"285\" y=\"136\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">预测强模型增益</text><path d=\"M360,105 L420,63\" stroke=\"#6b7484\" marker-end=\"url(#mr1)\"/><path d=\"M360,139 L420,184\" stroke=\"#6b7484\" marker-end=\"url(#mr1)\"/><rect x=\"422\" y=\"31\" width=\"140\" height=\"64\" rx=\"9\" fill=\"#21252d\" stroke=\"#c77b72\"/><text x=\"492\" y=\"56\" text-anchor=\"middle\" class=\"svg-t\">g≥τ → 强模型</text><text x=\"492\" y=\"77\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">升级率与成本上升</text><rect x=\"422\" y=\"161\" width=\"140\" height=\"64\" rx=\"9\" fill=\"#21252d\" stroke=\"#4f9d78\"/><text x=\"492\" y=\"186\" text-anchor=\"middle\" class=\"svg-t\">g&lt;τ → 小模型</text><text x=\"492\" y=\"207\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">覆盖高但可能错放</text><path d=\"M562,193 C650,196 662,104 566,65\" fill=\"none\" stroke=\"#6b7484\" stroke-dasharray=\"5 4\" marker-end=\"url(#mr1)\"/><text x=\"626\" y=\"137\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">随机双跑/人工审计</text><text x=\"626\" y=\"153\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">补反事实标签并重校准</text></svg><figcaption>图 1　路由分数要预测升级收益；下放样本必须抽样双跑或人工审计，否则系统看不见自己错放的请求。</figcaption></figure><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>阈值</th><th>升级数</th><th>错放困难请求</th><th>质量通过</th><th>平均模型成本</th><th>升级请求延迟</th></tr></thead><tbody><tr><td>τ=.7</td><td>150</td><td>28</td><td>91.0%</td><td>.02+.15×.10=¥.035</td><td>S+判定+L</td></tr><tr><td>τ=.5</td><td>250</td><td>12</td><td>93.1%</td><td>¥.045</td><td>S+判定+L</td></tr><tr><td>τ=.3</td><td>420</td><td>4</td><td>94.0%</td><td>¥.062</td><td>S+判定+L</td></tr></tbody></table></div><p>若门槛是质量≥93%、错放≤15，则 τ=.5 是最低成本可行点。若高风险切片在这 12 个错放中占 5 个并超过独立门槛，仍需对该切片强制升级，而不是全局阈值继续平均。</p><p>阈值案例输入 1000 笔请求、升级分数 g(x)、阈值 τ 和三组质量成本结果，输出满足质量与错放门槛的最低成本阈值。τ 降低会增加升级、成本并减少错放；τ=.5 只在全局与所有关键切片同时通过时可选。高风险切片失败需强制升级，不能靠全局平均掩盖。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>路由信号必须在决策时可得且可校准<span class=\"dd-badge eng\">特征</span></h2><p class=\"dd-lead\">哪些特征真正能预测强模型比小模型更有价值？</p><p>输入领域、长度、语言、风险规则、检索命中与证据冲突可在调用前获得；小模型 logprob、自一致分歧、格式校验和外部验证需先运行首答。训练时不能使用最终人工标签、未来工具状态或只有强模型运行后才知道的特征，否则离线路由器会数据泄漏。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>信号</th><th>阶段</th><th>盲区</th></tr></thead><tbody><tr><td>规则/元数据</td><td>调用前</td><td>新型困难与代理歧视</td></tr><tr><td>小模型 logprob</td><td>首答后</td><td>流畅错误、长度偏差、失准</td></tr><tr><td>多样本分歧</td><td>首答后</td><td>成本高、可能一致地错</td></tr><tr><td>检索/验证器</td><td>工具后</td><td>验证覆盖与自身错误</td></tr><tr><td>历史群体特征</td><td>调用前</td><td>公平、隐私和分布漂移</td></tr></tbody></table></div><p>将分数在独立集上校准为“升级能修复的概率”，按切片画可靠性图。模型说“我有 90% 把握”不能直接成为路由阈值。</p><p>路由特征输入决策时已经可得的领域、长度、语言、风险、检索、首答或验证信号，输出经独立集校准的“升级可修复概率”。训练时使用未来标签或强模型后验信息会数据泄漏；分数可靠性必须按切片检查。模型自报置信度不能未经校准直接当阈值。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>错误下放会集中在谁身上<span class=\"dd-badge eng\">安全与公平</span></h2><p class=\"dd-lead\">平均质量合格，为什么长尾语言和专业用户仍可能系统性得到弱模型？</p><p>路由器通常在多数语言和常见任务上训练，可能把短输入误判为简单，把少数语言的低置信当噪声，或用地区、账户等级等代理让服务质量不公平。报告每个切片的下放率、强对小错率、错放率、升级收益和置信区间。</p><p>高影响领域可不依赖学习路由：医疗、金融决策、权限写操作与明确合规关键词强制更强验证或人工。公平并非要求所有群体升级比例相同，而是错误与服务质量不因路由策略造成不可接受差距。</p><div class=\"dd-note warn\"><b>反馈环：</b>小模型服务的用户更可能流失，从未来日志消失；若只用留下来的交互训练路由器，会错误地认为下放成功。</div><p>公平评测输入语言、领域、用户群和风险切片，输出各切片下放率、强对小错率、错放率、升级收益与置信区间。平均合格可能隐藏长尾用户持续收到弱模型；公平目标是限制不可接受的质量与错误差距，不是强求相同升级比例。高影响任务可直接绕过学习路由。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>路由器上线也需要探索、监控与回退<span class=\"dd-badge eng\">运维</span></h2><p class=\"dd-lead\">底层模型、价格或流量一变，旧阈值为什么会立即失真？</p><p>路由标签是候选模型之间的相对差异；任一模型版本、提示、价格、检索质量或流量变化都会改变最优边界。记录路由分数、选择原因、候选版本、升级率、逐切片质量、成本和级联延迟。新版本先离线双跑、影子，再金丝雀。</p><ol class=\"dd-steps\"><li>对少量下放请求随机运行强模型或人工审计，估错放反事实。</li><li>按时间和切片监控分数分布、校准与升级收益。</li><li>若质量标签延迟，先看证据缺失、用户纠正和人工改判代理。</li><li>越权或错放超预算时切到保守规则：全量强模型/人工或禁用动作。</li><li>重新收集双跑数据再校准，而不是只移动阈值掩盖根因。</li></ol><p>探索会增加成本和潜在风险，必须限于安全可双跑的请求；不可逆工具只让一个经批准路径执行。</p><p>在线治理输入模型版本、价格、流量、路由分数、选择原因和延迟质量反馈，输出探索审计、重校准、金丝雀或保守回退动作。随机双跑让系统看见下放反事实，漂移则触发重新收集数据；错放超预算时先禁用危险动作或全量升级，不能只移动阈值掩盖根因。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">9</span>常见误区与概念依赖<span class=\"dd-badge intuition\">常见误区与学习路线</span></h2><p class=\"dd-lead\">路由系统的核心产品是“安全下放证据”，不是一张节省百分比图。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>小模型比例越高越好</td><td>应最大化满足切片门槛的安全覆盖</td></tr><tr><td>输入越短越简单</td><td>短提示也可能含专业或高风险歧义</td></tr><tr><td>低 logprob 就升级</td><td>原始概率需校准且会漏掉自信错误</td></tr><tr><td>级联一定省钱</td><td>升级请求支付 S+判定+L 并增加尾延迟</td></tr><tr><td>只看已升级样本可训练路由</td><td>缺少下放样本的反事实强模型结果</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>概念依赖与延伸学习</th></tr></thead><tbody><tr><td>先修</td><td>模型选型、应用评测、不确定性校准</td></tr><tr><td><b>本页核心</b></td><td>直接路由、级联、质量差预测、阈值、反事实审计</td></tr><tr><td>系统</td><td>部署、推理优化、提示缓存、人在回路</td></tr><tr><td>治理</td><td>数据漂移、公平性、可观测性与安全回退</td></tr></tbody></table></div></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">10</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>建立候选逐样本质量与成本基线</li><li>定义高风险强制规则</li><li>训练/校准强模型增益分数</li><li>选择满足切片门槛的阈值</li><li>灰度路由并随机审计下放样本</li><li>版本或分布变化后重校准/回退</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">11</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>模型路由与 MoE 有何区别？</li><li>级联平均模型成本公式是什么？</li><li>为什么应预测强模型相对增益？</li><li>为何要随机双跑下放样本？</li><li>何时强制绕过概率路由？</li><li>假设“模型路由与级联：把不同难度请求分给足够的能力”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li><li>如何为“模型路由与级联：把不同难度请求分给足够的能力”设计一个最小对照实验，证明观察到的改善来自核心机制，而不是数据、提示、权限或评测口径同时变化？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>路由在应用层选择完整模型/服务；MoE 在单个模型内部为 token 选择专家。</li><li>所有请求先跑 S 时为 C_S+rC_L，另加判定、工具和失败成本。</li><li>绝对困难不等于升级有用；两模型同对或同错都不值得因增益而升级。</li><li>取得反事实强模型结果，发现被路由器隐藏的错误下放。</li><li>高影响、权限写操作或明确合规场景可直接强模型、验证或人工。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li><li>固定数据、模型版本、提示、权限、预算和评测，只改变一个与核心机制直接相关的因素，并在多个样本与随机种子上重复；同时保存中间状态和失败样本。若差异只在目标因素变化时稳定出现，才支持机制解释，否则应继续排查混杂变量。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/2305.05176\" target=\"_blank\" rel=\"noopener\">FrugalGPT</a>：模型级联与预算优化</li><li><a href=\"https://arxiv.org/abs/2406.18665\" target=\"_blank\" rel=\"noopener\">RouteLLM</a>：偏好数据驱动的强弱模型路由</li><li><a href=\"https://arxiv.org/abs/2410.13284\" target=\"_blank\" rel=\"noopener\">Learning to Route LLMs with Confidence Tokens</a>：基于置信信号的路由</li><li><a href=\"https://arxiv.org/abs/1705.08500\" target=\"_blank\" rel=\"noopener\">Selective Classification for Deep Neural Networks</a>：风险—覆盖与选择性决策</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
